import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Remaining roadmap","description":"The path from partial completion to a long-running v1.0.","frontmatter":{"title":"Remaining roadmap","description":"The path from partial completion to a long-running v1.0.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/roadmap.md","filePath":"en/delivery/roadmap.md","lastUpdated":1793797632000}'),r={name:"en/delivery/roadmap.md"};function n(l,e,s,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="remaining-roadmap" tabindex="-1">Remaining roadmap <a class="header-anchor" href="#remaining-roadmap" aria-label="Permalink to &quot;Remaining roadmap&quot;">​</a></h1><p class="lead">The remaining route is organized by missing real acceptance, not by which module to write next. Every workstream needs an explicit exit condition; merged code or a finished page does not advance a phase.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>Real acceptance before new surface.</strong> Capabilities that already have code loops must be proven with real accounts, devices, or tasks before expanding.</li><li><strong>Risk before coverage.</strong> Desktop high-risk actions, external writes, lost devices, and backup restore need failure drills first.</li><li><strong>Evidence before conclusion.</strong> Keep inputs, run manifests, artifact digests, approvals, and receipts; keep failures too.</li><li><strong>No automatic promotion.</strong> Phase status is decided by acceptance records, not commit count, page count, or test count.</li></ol><h2 id="seven-workstreams" tabindex="-1">Seven workstreams <a class="header-anchor" href="#seven-workstreams" aria-label="Permalink to &quot;Seven workstreams&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workstream</th><th>Goal</th><th>Exit condition</th></tr></thead><tbody><tr><td>W1 Everyday content acceptance</td><td>Connect real email/calendar and close the everyday content loop</td><td>10–15 real tasks with time, accuracy, recovery, and user willingness recorded</td></tr><tr><td>W2 Desktop safety and high risk</td><td>Add masking, isolated desktop, high-risk actions, and compensation</td><td>At least 5 real desktop tasks; sensitive areas never leak; takeover and failure drills pass</td></tr><tr><td>W3 Mobile entry and proactive service</td><td>Mobile approval/takeover with controlled interruption</td><td>PWA pairing, push, remote approval; 5–10 proactive tasks average at most one interruption each</td></tr><tr><td>W4 Memory and method production comparison</td><td>Prove memory and methods help and can roll back</td><td>Wrong-memory/wrong-method drills; before/after success, human time, and cost comparison</td></tr><tr><td>W5 Multi-device and lost device</td><td>Real two-device switch, revocation, and restore</td><td>Offline recovery, lost device, token rotation, backup restore, and migration verification</td></tr><tr><td>W6 Long-running operation and upgrade</td><td>Multi-week run and upgrade rollback</td><td>Resource/state drift data; failed upgrade can roll back; full task-type regression matrix</td></tr><tr><td>W7 v1.0 release</td><td>An installable, upgradeable, removable version</td><td>Install/upgrade/migration/exit acceptance; release notes and known limits</td></tr></tbody></table><h2 id="w1-·-everyday-content-acceptance" tabindex="-1">W1 · Everyday content acceptance <a class="header-anchor" href="#w1-·-everyday-content-acceptance" aria-label="Permalink to &quot;W1 · Everyday content acceptance&quot;">​</a></h2><p><strong>Why now:</strong> sources, extraction, drafts, approvals, and the local outbox have code loops, but there is no real account or send receipt. Without this, phase two is not complete.</p><p><strong>Work:</strong></p><ul><li>Connect one real test mailbox and one calendar account, read-only first, then write.</li><li>Cover 10–15 real everyday tasks: mail summaries, calendar cleanup, document extraction, table cleanup, web archiving, and draft replies.</li><li>Record duration, human edits, failure causes, and recovery for each task.</li><li>Make the UI difference between &quot;local outbox&quot; and &quot;real send&quot; unmistakable.</li></ul><p><strong>Exit:</strong></p><ul><li>At least 10 tasks pass, and failed tasks have recoverable records.</li><li>Real sends have receipts; when nothing was sent, the UI says so.</li><li>The user can verify sources, artifacts, and external actions without reading internal logs.</li></ul><h2 id="w2-·-desktop-safety-and-high-risk" tabindex="-1">W2 · Desktop safety and high risk <a class="header-anchor" href="#w2-·-desktop-safety-and-high-risk" aria-label="Permalink to &quot;W2 · Desktop safety and high risk&quot;">​</a></h2><p><strong>Why now:</strong> the Windows helper can pair, observe, take over, and execute low-risk actions, but sensitive-area masking, isolated desktop, high-risk confirmation, and compensation are missing. Expanding desktop automation without these boundaries is not acceptable.</p><p><strong>Work:</strong></p><ul><li>Sensitive-area masking and redaction in screenshots.</li><li>High-risk action preview, second confirmation, and recoverable compensation.</li><li>Isolated desktop or an equivalent verified input boundary.</li><li>Failure drills for window loss, permission changes, user takeover, and UIA setvalue.</li></ul><p><strong>Exit:</strong></p><ul><li>At least 5 real desktop tasks with success rate, takeover count, and failure causes recorded.</li><li>Sensitive areas never enter screenshots, logs, or model context.</li><li>High-risk actions cannot execute without explicit approval.</li></ul><h2 id="w3-·-mobile-entry-and-proactive-service" tabindex="-1">W3 · Mobile entry and proactive service <a class="header-anchor" href="#w3-·-mobile-entry-and-proactive-service" aria-label="Permalink to &quot;W3 · Mobile entry and proactive service&quot;">​</a></h2><p><strong>Why now:</strong> proactive suggestions, the inbox, and attention budget exist, but the entry is same-machine web only. Mobile PWA, pairing, push, and remote approval are missing.</p><p><strong>Work:</strong></p><ul><li>Mobile PWA and short-lived pairing.</li><li>Push/notification channel and delivery records.</li><li>Mobile approval, rejection, snooze, and takeover.</li><li>5–10 real proactive interruption tests.</li></ul><p><strong>Exit:</strong></p><ul><li>The phone can approve and take over; a lost phone can be revoked immediately.</li><li>Proactive tasks average at most one interruption per task.</li><li>The user can pause temporarily, set quiet hours, and inspect budget use.</li></ul><h2 id="w4-·-memory-and-method-production-comparison" tabindex="-1">W4 · Memory and method production comparison <a class="header-anchor" href="#w4-·-memory-and-method-production-comparison" aria-label="Permalink to &quot;W4 · Memory and method production comparison&quot;">​</a></h2><p><strong>Why now:</strong> memory candidates, recall, correction, forgetting, method evaluation, promotion, and rollback have code loops, but lack real long-term use and before/after comparison.</p><p><strong>Work:</strong></p><ul><li>Wrong-memory injection, correction, forgetting, and export verification.</li><li>Wrong-method drill: a candidate cannot expand authority and failure must roll back.</li><li>Baseline/after comparison on real tasks: success, human time, tokens, and approvals.</li></ul><p><strong>Exit:</strong></p><ul><li>Wrong memory can be found, corrected, and forgotten; export excludes forgotten bodies.</li><li>Promotion has trial evidence; rollback keeps reasons and audit.</li><li>At least one real task group proves the adopted method is better, or records no improvement explicitly.</li></ul><h2 id="w5-·-multi-device-and-lost-device" tabindex="-1">W5 · Multi-device and lost device <a class="header-anchor" href="#w5-·-multi-device-and-lost-device" aria-label="Permalink to &quot;W5 · Multi-device and lost device&quot;">​</a></h2><p><strong>Why now:</strong> incremental sync, peer auth, leases, revocation, token rotation, and encrypted backup exist, but there is no real two-device run, offline recovery, or lost-device drill.</p><p><strong>Work:</strong></p><ul><li>Two real devices complete incremental sync and task takeover.</li><li>Offline, recovery, conflict, and epoch-fencing drills.</li><li>Lost-device revocation, token rotation, and read-blocking verification.</li><li>Verify task, artifact, and workspace boundaries after encrypted backup restore.</li></ul><p><strong>Exit:</strong></p><ul><li>Two devices can switch tasks and old-owner commits are rejected.</li><li>A revoked device cannot approve, take over, or read.</li><li>Backup restore is repeatable and explicitly lists excluded artifacts and attachments.</li></ul><h2 id="w6-·-long-running-operation-and-upgrade" tabindex="-1">W6 · Long-running operation and upgrade <a class="header-anchor" href="#w6-·-long-running-operation-and-upgrade" aria-label="Permalink to &quot;W6 · Long-running operation and upgrade&quot;">​</a></h2><p><strong>Why now:</strong> health snapshots, maintenance, diagnostics, and encrypted backup exist, but there is no multi-week run, resource-drift data, or upgrade rollback evidence.</p><p><strong>Work:</strong></p><ul><li>Run for at least several weeks, recording memory, disk, task backlog, and maintenance results.</li><li>Build an app version upgrade and failed-upgrade rollback pipeline.</li><li>Build a full task-type regression matrix.</li><li>Drill incompatible schema, maintenance failure, and diagnostics export.</li></ul><p><strong>Exit:</strong></p><ul><li>No unrecoverable state drift during continuous operation.</li><li>Failed upgrade can roll back without data loss.</li><li>Maintenance failure marks health degraded and produces redacted diagnostics.</li></ul><h2 id="w7-·-v1-0-release" tabindex="-1">W7 · v1.0 release <a class="header-anchor" href="#w7-·-v1-0-release" aria-label="Permalink to &quot;W7 · v1.0 release&quot;">​</a></h2><p><strong>Why last:</strong> v1.0 is not &quot;more features&quot;; it is install, upgrade, migration, exit, and known limits that a user can verify.</p><p><strong>Work:</strong></p><ul><li>Installer or one-command startup.</li><li>Upgrade, migration, and exit instructions.</li><li>Release notes, known limits, and support boundaries.</li><li>Final overall acceptance.</li></ul><p><strong>Exit:</strong></p><ul><li>A new user can install, configure, and use Hearth without reading source code.</li><li>Upgrade and migration have rollback paths.</li><li>Release notes do not describe partial work as complete.</li></ul><h2 id="milestone-order" tabindex="-1">Milestone order <a class="header-anchor" href="#milestone-order" aria-label="Permalink to &quot;Milestone order&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Workstreams</th><th>Completion signal</th></tr></thead><tbody><tr><td>M1 Usability convergence</td><td>W1, W2</td><td>Real everyday-content and desktop tasks pass; high-risk boundaries are provable</td></tr><tr><td>M2 Entry and learning</td><td>W3, W4</td><td>Mobile approval works; memory/methods have production comparisons</td></tr><tr><td>M3 Reliability and migration</td><td>W5, W6</td><td>Two-device, lost-device, long-running, and upgrade-rollback evidence exists</td></tr><tr><td>M4 v1.0</td><td>W7</td><td>Install, upgrade, migration, exit, and release notes are complete</td></tr></tbody></table><p>Milestones can run in parallel, but exit conditions cannot be skipped. If a workstream lacks real evidence, later milestones remain &quot;partial&quot;.</p><h2 id="explicit-non-goals" tabindex="-1">Explicit non-goals <a class="header-anchor" href="#explicit-non-goals" aria-label="Permalink to &quot;Explicit non-goals&quot;">​</a></h2><ul><li>Do not turn proactive suggestions into an auto-executor.</li><li>Do not let the model expand tool, network, or approval authority on its own.</li><li>Do not replace real acceptance with simulated email, simulated devices, or fake data.</li><li>Do not expand high-risk desktop actions without failure drills.</li><li>Do not split into microservices or multi-agent teams just to look complete.</li></ul><h2 id="stop-conditions" tabindex="-1">Stop conditions <a class="header-anchor" href="#stop-conditions" aria-label="Permalink to &quot;Stop conditions&quot;">​</a></h2><p>Pause expansion and return to risk and recovery when:</p><ul><li>Real tasks fail repeatedly without explanation.</li><li>External actions duplicate or cannot be reconciled.</li><li>A revoked device can still read or operate.</li><li>Backup restore produces unexplained data loss.</li><li>The user cannot tell whether a task finished without reading internal logs.</li></ul><p>See <a href="/hearth-os/en/reference/risks.html">Risks and stop conditions</a> for more.</p>',57)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
